from AlgorithmImports import *


class IndependentSlotsAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0
        self.previous_aapl_close = None

        self.lots = {"A": 0, "B": 0}
        self.pending_orders = {}

    def OnData(self, data: Slice):
        # Market-state quantities are updated continuously whenever their bars exist.
        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            if aapl_bar.Close < aapl_bar.Open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Do not evaluate any rule unless every subscribed ticker has today's bar.
        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            self._store_previous_values(data)
            return

        # Do not trade until every indicator/window used by a rule is fully formed.
        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self._store_previous_values(data)
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        spy_crosses_above = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and spy_close > self.spy_sma.Current.Value
        )

        spy_crosses_below = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and spy_close < self.spy_sma.Current.Value
        )

        # Sells are evaluated before buys.
        if self.lots["A"] > 0 and "A" not in self.pending_orders and spy_crosses_below:
            self._submit_lot_order("A", self.spy, -self.lots["A"])

        if self.lots["B"] > 0 and "B" not in self.pending_orders and self.aapl_rsi.Current.Value > 60:
            self._submit_lot_order("B", self.aapl, -self.lots["B"])

        if self.lots["A"] == 0 and "A" not in self.pending_orders and spy_crosses_above:
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_close)
            if quantity > 0:
                self._submit_lot_order("A", self.spy, quantity)

        if self.lots["B"] == 0 and "B" not in self.pending_orders and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self._submit_lot_order("B", self.aapl, quantity)

        self._store_previous_values(data)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
            if order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                for slot, order_id in list(self.pending_orders.items()):
                    if order_id == order_event.OrderId:
                        del self.pending_orders[slot]
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        slot = order.Tag
        if slot not in self.lots:
            return

        self.lots[slot] += order_event.FillQuantity

        if order_event.Status == OrderStatus.Filled:
            self.lots[slot] = max(0, self.lots[slot])
            self.pending_orders.pop(slot, None)

    def _submit_lot_order(self, slot, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity, tag=slot)
        self.pending_orders[slot] = ticket.OrderId

    def _store_previous_values(self, data):
        if data.Bars.ContainsKey(self.spy):
            self.previous_spy_close = data.Bars[self.spy].Close
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value

        if data.Bars.ContainsKey(self.aapl):
            self.previous_aapl_close = data.Bars[self.aapl].Close
