        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and spy_ready:
            closes = [self.spy_closes[i] for i in range(101)]
            today_close = closes[0]
            yesterday_close = closes[1]
            today_sma = sum(closes[0:100]) / 100.0
            yesterday_sma = sum(closes[1:101]) / 100.0

            if yesterday_close >= yesterday_sma and today_close < today_sma:
